import {
  HTMLAttributes,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'preact/compat';
import { Container, Slot, SlotProps } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import { ProductModel } from '@/pdp/data/models';
import { events } from '@adobe-commerce/event-bus';
import { Swatches } from '@/pdp/components';
import {
  setProductConfigurationValues,
  getProductConfigurationValues,
  setProductConfigurationValid,
  fetchProductData,
  getFetchedProductData,
  config,
  OptionsTransformer,
} from '@/pdp/api';
import { setUrlParams } from '@/pdp/lib/url-params';
import { publishProductPageViewEvent } from '@/pdp/lib/acdl';
import {
  ImageNodeRenderProps,
  ImageProps,
} from '@adobe-commerce/elsie/components';
import {
  type ProductOptionSelectionMap,
  isProductOptionsSelectionComplete,
  selectionMapToOptionUIDs,
} from '@/pdp/lib/product-option-selection';
import {
  bundleOptionQuantitiesToEnteredOptions,
  mergeBundleOptionQuantities,
} from '@/pdp/lib/bundle-option-quantities';

/** @deprecated Use OptionsTransformer from @/pdp/api instead */
export type ProductOptionsTransformer = OptionsTransformer;

export interface ProductOptionsProps extends HTMLAttributes<HTMLDivElement> {
  scope?: string;
  hideSelectedValue?: boolean;
  onValues?: (optionsUIDs: string[]) => void;
  onErrors?: (errors: { [id: string]: string }) => void;
  transformer?: ProductOptionsTransformer;
  slots?: {
    Swatches?: SlotProps<{ data: ProductModel | null; optionsUIDs: string[] }>;
    SwatchImage?: SlotProps<{
      data: ProductModel | null;
      optionsUIDs: string[];
      imageSwatchContext: ImageNodeRenderProps['imageSwatchContext'];
      defaultImageProps: ImageProps;
    }>;
  };
}

export const ProductOptions: Container<
  ProductOptionsProps,
  { data: ProductModel | null; optionsUIDs: string[] }
> = ({
  initialData = { data: null, optionsUIDs: [] },
  scope,
  hideSelectedValue = false,
  transformer,
  slots,
  onValues,
  onErrors,
  children,
  ...props
}) => {
  const [data, setData] = useState<ProductModel | null>(initialData.data);

  const [current, setCurrent] = useState<string[]>(initialData.optionsUIDs);
  const [bundleOptionQuantities, setBundleOptionQuantities] = useState<
    Record<string, number>
  >({});

  const [selectionsToUpdate, setSelectionsToUpdate] =
    useState<ProductModel['options']>();

  const ChooseOptionLabel = useText('PDP.Swatches.ChooseOption.label').label;

  // Apply transformer to options if provided (must run before selection handlers)
  const transformedOptions = useMemo(() => {
    if (!data?.options) return undefined;

    if (!transformer) {
      return data.options;
    }

    try {
      const transformed = transformer(data.options);
      // Fallback to original options if transformer returns null/undefined
      return transformed ?? data.options;
    } catch (error) {
      console.error(
        'ProductOptions: transformer threw an error, using original options',
        error
      );
      return data.options;
    }
  }, [data?.options, transformer]);

  useEffect(() => {
    const dataEvent = events.on('pdp/data', setData, { scope });

    const valuesEvent = events.on(
      'pdp/values',
      ({ optionsUIDs, bundleOptionQuantities }) => {
        if (optionsUIDs) {
          setCurrent(optionsUIDs);
        }
        if (bundleOptionQuantities) {
          setBundleOptionQuantities(bundleOptionQuantities);
        }
      },
      { scope }
    );

    return () => {
      dataEvent?.off();
      valuesEvent?.off();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleOptionSelected = useCallback(
    async (selections: ProductOptionSelectionMap) => {
      if (!data?.sku) return;

      const { persistURLParams, anchors, acdl } = config.getConfig() ?? {};

      const sanitizedSelections = Object.fromEntries(
        Object.entries(selections).filter(
          ([, value]) => value.label !== ChooseOptionLabel
        )
      ) as ProductOptionSelectionMap;

      // options selected
      let optionsUIDs = selectionMapToOptionUIDs(
        sanitizedSelections,
        transformedOptions
      );

      // set optionUIDs to URL params
      // ?optionsUIDs=1,2,3
      // only set the URL params if the "persistURLParams" is set to true and the product is not a bundle type
      if (persistURLParams && !data?.isBundle) {
        setUrlParams({ optionsUIDs: optionsUIDs.join(',') });
      }

      const storedOptionsUIDs =
        getProductConfigurationValues({ scope })?.optionsUIDs ?? [];

      const optionsChanged =
        storedOptionsUIDs.join('|') !== optionsUIDs.join('|');

      // check if the options have changed and update the values only if they have changed
      if (optionsChanged && !data?.isBundle) {
        setProductConfigurationValues((prev) => ({ ...prev, optionsUIDs }), {
          scope,
        });
      }

      // pass the selected options to callback
      onValues?.(optionsUIDs);

      // refetch data
      const next = await fetchProductData(data.sku, {
        optionsUIDs: optionsUIDs ?? [],
        isBundle: data?.isBundle,
        anchors,
      });

      // emit the new data
      events.emit('pdp/data', next, { scope });

      const syncBundleOptionQuantities = (finalOptionsUIDs: string[]) => {
        if (!data?.isBundle || !next?.options) {
          return;
        }

        setProductConfigurationValues(
          (prev) => {
            const bundleOptionQuantities = mergeBundleOptionQuantities(
              prev.bundleOptionQuantities,
              next.options,
              finalOptionsUIDs
            );

            return {
              ...prev,
              optionsUIDs: finalOptionsUIDs,
              bundleOptionQuantities,
              enteredOptions: bundleOptionQuantitiesToEnteredOptions(
                bundleOptionQuantities
              ),
            };
          },
          { scope }
        );
      };

      let finalOptionsUIDs = next?.optionUIDs ?? optionsUIDs;

      let valid = isProductOptionsSelectionComplete(
        next?.options,
        finalOptionsUIDs,
        next?.isBundle
      );

      // special processing for anchor options (options that should not be refined when other options are selected)
      if (anchors?.length) {
        const updatedOptionsUIDs = next?.optionUIDs ?? [];

        const isMatching = optionsUIDs.every((item) =>
          updatedOptionsUIDs.includes(item)
        );

        if (!isMatching) {
          setSelectionsToUpdate(next?.options);
          finalOptionsUIDs = updatedOptionsUIDs;

          if (!data?.isBundle) {
            setProductConfigurationValues(
              (prev) => ({
                ...prev,
                optionsUIDs: updatedOptionsUIDs,
              }),
              { scope }
            );
          }

          valid = isProductOptionsSelectionComplete(
            next?.options,
            updatedOptionsUIDs,
            next?.isBundle
          );
        }
      }

      if (storedOptionsUIDs.join('|') !== finalOptionsUIDs.join('|')) {
        syncBundleOptionQuantities(finalOptionsUIDs);
      }

      // is the product valid
      setProductConfigurationValid(() => valid, { scope });

      // ACDL
      if (acdl && next && next?.variantSku !== data.sku) {
        publishProductPageViewEvent(next);
      }
    },
    [
      ChooseOptionLabel,
      data?.isBundle,
      data?.sku,
      onValues,
      scope,
      transformedOptions,
    ]
  );

  const handleBundleOptionQuantityChange = useCallback(
    (optionValueId: string, quantity: number) => {
      const optionValue = transformedOptions
        ?.flatMap((option) => option.items)
        .find((item) => item.id === optionValueId);

      if (!optionValue?.canEditQuantity) {
        return;
      }

      setProductConfigurationValues(
        (prev) => {
          const bundleOptionQuantities = {
            ...(prev.bundleOptionQuantities ?? {}),
            [optionValueId]: quantity,
          };
          return {
            ...prev,
            bundleOptionQuantities,
            enteredOptions: bundleOptionQuantitiesToEnteredOptions(
              bundleOptionQuantities
            ),
          };
        },
        { scope }
      );
    },
    [scope, transformedOptions]
  );

  const handleErrors = useCallback(
    (errors: { [id: string]: string }) => {
      const hasErrors = Object.keys(errors).length !== 0;

      if (hasErrors) {
        setProductConfigurationValid(() => false, { scope });
        onErrors?.(errors);
      }
    },
    [onErrors, scope]
  );

  if (!data) return null;

  // Only show if there are options in the data
  if (!transformedOptions) return null;

  return (
    <Slot
      name="Swatches"
      slot={slots?.Swatches}
      context={{ data, optionsUIDs: current }}
    >
      <Swatches
        {...props}
        options={transformedOptions}
        selectedUIDs={current}
        defaultOptions={current}
        selectionsToUpdate={selectionsToUpdate}
        hideSelectedValue={hideSelectedValue}
        disablePreselections={!config.getConfig()?.preselectFirstOption}
        onValues={handleOptionSelected}
        onErrors={handleErrors}
        bundleOptionQuantities={bundleOptionQuantities}
        onBundleOptionQuantityChange={handleBundleOptionQuantityChange}
        imageSwatchNode={
          slots?.SwatchImage
            ? ({ imageSwatchContext, ...imageProps }) => (
                <Slot
                  name="SwatchImage"
                  slot={slots?.SwatchImage}
                  slotTag="span"
                  contentTag="span"
                  context={{
                    data,
                    optionsUIDs: current,
                    defaultImageProps: imageProps,
                    imageSwatchContext,
                  }}
                />
              )
            : undefined
        }
      />
    </Slot>
  );
};

ProductOptions.getInitialData = async function (options) {
  const data = await getFetchedProductData({ scope: options?.scope });
  const optionsUIDs =
    getProductConfigurationValues({ scope: options?.scope })?.optionsUIDs ?? [];
  return { data, optionsUIDs };
};
